def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    opp_need_pressure = 0
    rich_aggressive = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                opp_need_pressure += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = prev.get('bid', 0.0)
                prev_bids.append(bid)
                if bid >= 140 and opp.get('budget', 0) >= 200:
                    rich_aggressive += 1

    if not alive_opponents:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgent = False
    if hp <= 2:
        urgent = True
    if no_water >= 1 and hp <= 4:
        urgent = True
    if no_water >= 2:
        urgent = True

    if urgent:
        target = max(150.0, highest_prev + 6.0)
        if supply <= 16:
            target = max(target, 178.0)
        return min(budget, target)

    if hp >= 7 and no_water == 0:
        if highest_prev >= 150 or rich_aggressive >= 2:
            return min(budget, 12.0 if supply >= 20 else 20.0)
        if scarcity == 0:
            return min(budget, max(28.0, avg_prev * 0.42))
        return min(budget, max(40.0, avg_prev * 0.5))

    if scarcity == 2:
        target = max(95.0, highest_prev * 0.72)
    elif scarcity == 1:
        target = max(78.0, avg_prev * 0.68)
    else:
        target = max(60.0, avg_prev * 0.58)

    if opp_need_pressure >= 2:
        target -= 10.0
    if highest_prev >= 180:
        target -= 12.0
    if hp <= 4:
        target += 18.0
    if no_water >= 1:
        target += 15.0
    if day >= 8 and hp <= 5:
        target += 12.0

    target = max(15.0, target)
    return min(budget, target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']

    # Alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read yesterday trace bids
    yesterday_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # If no trace info, use conservative baseline
    if not yesterday_bids:
        if my_status['hp'] <= 2:
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        return min(my_status['budget'], DAILY_SALARY * 0.55)

    highest_prev_bid = max(yesterday_bids)
    second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid

    # Pressure estimate: if others were spending aggressively, we can undercut slightly.
    # Target bid is a bit above the likely second-highest, but capped.
    target = second_prev_bid + 2.0

    # If someone was extremely aggressive, don't let them dictate: bid near their level only if needed.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_status['hp'] > 3:
            target = min(target, DAILY_SALARY * 0.35)
        else:
            target = min(target, DAILY_SALARY * 0.92)
    else:
        # Otherwise, bid moderately to secure water without overspending.
        if my_status['hp'] <= 2:
            target = max(target, DAILY_SALARY * 0.75)
        elif my_status['hp'] <= 3:
            target = max(target, DAILY_SALARY * 0.55)
        else:
            target = max(target, DAILY_SALARY * 0.45)

    # Supply-based adjustment: higher supply reduces competition; lower supply increases it.
    # supply is float; map to discrete bucket safely.
    if supply <= MIN_SUPPLY:
        target *= 1.05
    elif supply >= MAX_SUPPLY:
        target *= 0.95

    # No-water days increases urgency.
    no_water_days = my_status.get('no_water_days', 0)
    if no_water_days >= 2:
        target *= 1.18
    elif no_water_days >= 1:
        target *= 1.08

    # Final clamp to budget and reasonable cap.
    target = float(target)
    if my_status['budget'] <= 0:
        return 0.0
    if my_status['hp'] <= 1:
        cap = DAILY_SALARY * 1.0
    else:
        cap = DAILY_SALARY * 0.95

    bid = min(my_status['budget'], min(target, cap))

    # Ensure non-negative
    if bid < 0:
        bid = 0.0
    return bid

